import { BuildOptions, Page } from './types';
import type { SsgEngine } from './engine';
import type { TemplateBundle } from './templates';

/**
 * Configuration loaded from `ssg.config.ts`.
 *
 * The `plugins` array lists additional plugin modules (resolved from the
 * `./plugins/` directory) or inline plugin instances that extend the site.
 */
export interface SsgConfig {
  plugins?: Array<string | Plugin>;
  [key: string]: unknown;
}

/**
 * Shared state threaded through every plugin hook invocation. The core engine
 * owns this context; plugins read options and can contribute rendered output
 * files or transform pages in place.
 */
export interface PluginContext {
  config: SsgConfig;
  options: BuildOptions;
  pages: Page[];
  outputFiles: Map<string, string>;
  templateBundle?: TemplateBundle;
  engine: SsgEngine;
}

/**
 * A plugin participating in the SSG lifecycle.
 *
 * Hooks run in registration order across every loaded plugin:
 *   - onStart()       called once when the engine begins
 *   - beforeBuild()   called before content is collected
 *   - onFile(page)    called for every content file, in file order
 *   - afterBuild()    called after every page has been processed
 *   - onEnd()         called once when the engine finishes
 */
export interface Plugin {
  name: string;
  onStart?(ctx: PluginContext): void | Promise<void>;
  beforeBuild?(ctx: PluginContext): void | Promise<void>;
  afterBuild?(ctx: PluginContext): void | Promise<void>;
  onFile?(page: Page, ctx: PluginContext): void | Promise<void>;
  onEnd?(ctx: PluginContext): void | Promise<void>;
}

export type PluginHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onFile' | 'onEnd';

/**
 * Runs a lifecycle hook across all plugins in order, awaiting each hook to
 * completion before moving on to the next plugin.
 */
export class PluginPipeline {
  constructor(private readonly plugins: Plugin[]) {}

  getPlugins(): Plugin[] {
    return this.plugins;
  }

  async run(hook: PluginHook, ...args: unknown[]): Promise<void> {
    for (const plugin of this.plugins) {
      const fn = (plugin as Record<string, unknown>)[hook] as
        | ((...hookArgs: unknown[]) => unknown)
        | undefined;
      if (typeof fn === 'function') {
        await fn.apply(plugin, args);
      }
    }
  }
}

import * as path from 'path';
import { SsgConfig } from './plugin';

const DEFAULT_CONFIG_FILE = 'ssg.config.ts';

/**
 * Load the site configuration from `ssg.config.ts` (relative to the current
 * working directory). Returns an empty config when the file is absent.
 */
export async function loadConfig(configPath: string = DEFAULT_CONFIG_FILE): Promise<SsgConfig> {
  try {
    const full = path.resolve(process.cwd(), configPath);
    const loaded = require(full) as { default?: SsgConfig } | SsgConfig;
    const config = loaded && typeof loaded === 'object' ? loaded.default ?? loaded : {};
    return config as SsgConfig;
  } catch {
    return {};
  }
}

import * as path from 'path';
import { Plugin, SsgConfig } from './plugin';
import { MarkdownPlugin } from '../plugins/markdown';
import { TemplatePlugin } from '../plugins/templates';

export const PLUGIN_DIR = 'plugins';

/**
 * Resolve a plugin module located under the `./plugins/` directory. Supports
 * both a default-exported class and a default-exported plugin instance.
 */
function requirePluginModule(name: string): unknown {
  const base = path.resolve(process.cwd(), PLUGIN_DIR);
  return require(path.join(base, name));
}

function instantiate(entry: string): Plugin {
  const mod = requirePluginModule(entry) as
    | { default?: unknown }
    | undefined;
  const resolved = mod && typeof mod === 'object' ? mod.default ?? mod : mod;
  if (typeof resolved === 'function') {
    return new (resolved as new () => Plugin)();
  }
  if (resolved && typeof resolved === 'object') {
    return resolved as Plugin;
  }
  throw new Error(`plugin not found: ${entry}`);
}

/**
 * Build the plugin list. Built-in plugins (markdown, templates) are always
 * registered first; plugins configured in `ssg.config.ts` are appended in
 * order, so every hook runs across all of them sequentially.
 */
export async function loadPlugins(config: SsgConfig): Promise<Plugin[]> {
  const plugins: Plugin[] = [new MarkdownPlugin(), new TemplatePlugin()];

  const configured = config.plugins ?? [];
  for (const entry of configured) {
    if (typeof entry === 'string') {
      plugins.push(instantiate(entry));
    } else if (entry) {
      plugins.push(entry);
    }
  }

  return plugins;
}

import { promises as fs } from 'fs';
import * as path from 'path';
import { Plugin, PluginContext, PluginPipeline, SsgConfig } from './plugin';
import { BuildOptions, Page } from './types';

const DEFAULT_TEMPLATES_DIR = 'templates';

const CONTENT_EXTENSIONS = ['.md', '.markdown', '.mdown'];

function slugify(filename: string): string {
  const base = filename.replace(/\.(md|markdown|mdown)$/i, '');
  return base
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

async function collectMarkdownFiles(dir: string): Promise<string[]> {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  const files: string[] = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await collectMarkdownFiles(full)));
    } else if (
      entry.isFile() &&
      CONTENT_EXTENSIONS.includes(path.extname(entry.name).toLowerCase())
    ) {
      files.push(full);
    }
  }
  return files;
}

function makeSlug(file: string, contentDir: string): string {
  const rel = path.relative(contentDir, file);
  const parsed = path.parse(rel);
  const joined = parsed.dir ? path.join(parsed.dir, parsed.name) : parsed.name;
  return slugify(joined.replace(/\\/g, '/'));
}

async function dirExists(dir: string): Promise<boolean> {
  try {
    const stat = await fs.stat(dir);
    return stat.isDirectory();
  } catch {
    return false;
  }
}

/**
 * Core SSG engine.
 *
 * Owns the plugin pipeline and orchestrates the lifecycle hooks:
 * `onStart` -> `beforeBuild` -> `onFile` (per content file) -> `afterBuild`
 * -> write outputs -> `onEnd`. Plugins transform pages and contribute output
 * files; the engine is responsible for discovery, ordering, and writing.
 */
export class SsgEngine {
  private readonly pipeline: PluginPipeline;
  private readonly context: PluginContext;

  constructor(plugins: Plugin[], options: BuildOptions, config: SsgConfig = {}) {
    const normalized: BuildOptions = {
      ...options,
      templatesDir: options.templatesDir ?? DEFAULT_TEMPLATES_DIR,
    };
    this.pipeline = new PluginPipeline(plugins);
    this.context = {
      config,
      options: normalized,
      pages: [],
      outputFiles: new Map<string, string>(),
      engine: this,
    };
  }

  getContext(): PluginContext {
    return this.context;
  }

  /**
   * Run a full build lifecycle (used by the `build` command).
   */
  async build(): Promise<Page[]> {
    await this.pipeline.run('onStart', this.context);
    const pages = await this.rebuild();
    await this.pipeline.run('onEnd', this.context);
    return pages;
  }

  /**
   * Rebuild content without running start/end hooks (used by the dev server
   * to refresh the site on file changes).
   */
  async rebuild(): Promise<Page[]> {
    this.context.outputFiles.clear();
    await this.pipeline.run('beforeBuild', this.context);
    await this.collectContent();
    await this.pipeline.run('afterBuild', this.context);
    await this.writeOutputs();
    return this.context.pages;
  }

  /**
   * Run the serve lifecycle. The dev-server plugin starts the server during
   * `onStart`; the resulting server handle is returned to the caller.
   */
  async serve(): Promise<unknown> {
    const devPlugin = this.pipeline
      .getPlugins()
      .find((plugin) => plugin.name === 'dev-server') as
      | { getServer(): unknown }
      | undefined;
    if (!devPlugin || typeof devPlugin.getServer !== 'function') {
      throw new Error('dev-server plugin not loaded');
    }
    await this.pipeline.run('onStart', this.context);
    return devPlugin.getServer();
  }

  private async collectContent(): Promise<void> {
    const { contentDir } = this.context.options;
    if (!(await dirExists(contentDir))) {
      throw new Error(`content directory not found: ${contentDir}`);
    }

    const files = await collectMarkdownFiles(contentDir);
    files.sort();

    const pages: Page[] = [];
    for (const file of files) {
      const source = await fs.readFile(file, 'utf8');
      const slug = makeSlug(file, contentDir);
      const page: Page = {
        slug,
        title: slug,
        tags: [],
        content: source,
        html: source,
        sourcePath: file,
      };
      await this.pipeline.run('onFile', page, this.context);
      pages.push(page);
    }

    this.context.pages = pages;
  }

  private async writeOutputs(): Promise<void> {
    const { outputDir } = this.context.options;
    await fs.mkdir(outputDir, { recursive: true });
    for (const [name, content] of this.context.outputFiles) {
      await fs.writeFile(path.join(outputDir, name), content, 'utf8');
    }
  }
}

import { parseMarkdown } from '../src/markdown';
import { Plugin, PluginContext } from '../src/plugin';
import { Page } from '../src/types';

/**
 * Built-in plugin that parses raw Markdown content into structured pages.
 *
 * Runs during the `onFile` hook: it reads the raw source (frontmatter +
 * body) handed to it by the engine and replaces the placeholder page with
 * fully parsed page data, leaving template/layout rendering to later plugins.
 */
export class MarkdownPlugin implements Plugin {
  readonly name = 'markdown';

  async onFile(page: Page, _ctx: PluginContext): Promise<void> {
    const parsed = parseMarkdown(page.content, page.sourcePath, page.slug);
    page.slug = parsed.slug;
    page.title = parsed.title;
    page.date = parsed.date;
    page.tags = parsed.tags;
    page.content = parsed.content;
    page.html = parsed.html;
    page.sourcePath = parsed.sourcePath;
    page.template = parsed.template;
    page.layout = parsed.layout;
    page.data = parsed.data;
  }
}

import { loadTemplates, renderIndexTemplate, renderPageTemplate, TemplateBundle } from '../src/templates';
import { renderIndexHtml, renderPageHtml } from '../src/render';
import { Plugin, PluginContext } from '../src/plugin';
import { Page } from '../src/types';

function renderPageForBuild(page: Page, bundle: TemplateBundle): string {
  if (!bundle.exists) {
    if (page.template) {
      throw new Error(`template not found: "${page.template}" (no templates directory configured)`);
    }
    return renderPageHtml(page);
  }
  return renderPageTemplate(page, bundle);
}

function renderIndexForBuild(pages: Page[], bundle: TemplateBundle): string {
  return renderIndexTemplate(pages, bundle) ?? renderIndexHtml(pages);
}

/**
 * Built-in plugin that renders pages and the site index through Handlebars
 * templates.
 *
 * Templates are loaded during `beforeBuild`; each page is rendered in the
 * `onFile` hook and the index is rendered in `afterBuild`. Rendered output is
 * contributed to the engine's output files so the engine can write it to disk.
 */
export class TemplatePlugin implements Plugin {
  readonly name = 'templates';

  async beforeBuild(ctx: PluginContext): Promise<void> {
    ctx.templateBundle = await loadTemplates(ctx.options.templatesDir ?? 'templates');
  }

  onFile(page: Page, ctx: PluginContext): void {
    if (!ctx.templateBundle) {
      throw new Error('templates not loaded');
    }
    ctx.outputFiles.set(`${page.slug}.html`, renderPageForBuild(page, ctx.templateBundle));
  }

  afterBuild(ctx: PluginContext): void {
    if (!ctx.templateBundle) {
      throw new Error('templates not loaded');
    }
    ctx.outputFiles.set('index.html', renderIndexForBuild(ctx.pages, ctx.templateBundle));
  }
}

export const LIVERELOAD_PATH = '/__ssg_livereload';

/**
 * Browser-side client that connects to the live-reload WebSocket endpoint and
 * reloads the page when a `reload` message arrives.
 */
export function reloadClientScript(): string {
  return `<script>
(function () {
  var reconnectDelay = 500;
  function connect() {
    var ws = new WebSocket((location.protocol === 'https:' ? 'wss://' : 'ws://') + location.host + '${LIVERELOAD_PATH}');
    ws.onmessage = function (event) {
      if (event.data === 'reload') {
        location.reload();
      }
    };
    ws.onopen = function () {
      reconnectDelay = 500;
    };
    ws.onclose = function () {
      setTimeout(connect, reconnectDelay);
      reconnectDelay = Math.min(reconnectDelay * 2, 10000);
    };
  }
  connect();
})();
</script>`;
}

/**
 * Inject the live-reload client script into an HTML document just before the
 * closing `</body>` tag.
 */
export function injectReloadScript(html: string): string {
  const bodyClose = html.lastIndexOf('</body>');
  if (bodyClose === -1) {
    return html + '\n' + reloadClientScript();
  }
  return (
    html.slice(0, bodyClose) + reloadClientScript() + '\n' + html.slice(bodyClose)
  );
}

import { createServer, Server } from 'http';
import { promises as fs } from 'fs';
import * as path from 'path';
import chokidar from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { Plugin, PluginContext } from '../src/plugin';
import { injectReloadScript, LIVERELOAD_PATH } from '../src/livereload';
import type { ServeOptions, DevServer } from '../src/serve';

const DEFAULT_PORT = 3000;
const REBUILD_DEBOUNCE_MS = 100;
const WATCHER_SETTLE_MS = 250;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.pdf': 'application/pdf',
  '.map': 'application/json',
};

function resolveFilePath(urlPath: string, outputDir: string): string | null {
  let pathname: string;
  try {
    pathname = decodeURIComponent(urlPath.split('?')[0]).split('#')[0];
  } catch {
    return null;
  }
  const root = path.resolve(outputDir);
  const clean = pathname.replace(/^\/+/, '');
  const candidate = path.resolve(root, clean);
  if (candidate !== root && !candidate.startsWith(root + path.sep)) {
    return null;
  }
  return candidate;
}

async function fileStat(target: string): Promise<{ isDirectory: boolean } | null> {
  try {
    const stat = await fs.stat(target);
    return { isDirectory: stat.isDirectory() };
  } catch {
    return null;
  }
}

async function serveFile(
  reqUrl: string,
  outputDir: string,
  res: import('http').ServerResponse
): Promise<void> {
  const file = resolveFilePath(reqUrl, outputDir);
  if (!file) {
    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Forbidden');
    return;
  }

  let target = file;
  let stat = await fileStat(target);
  if (stat && stat.isDirectory) {
    target = path.join(target, 'index.html');
    stat = await fileStat(target);
  }
  if (!stat) {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Not Found');
    return;
  }

  const ext = path.extname(target).toLowerCase();
  const data = await fs.readFile(target);
  if (ext === '.html') {
    const body = data.toString('utf8');
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(injectReloadScript(body));
    return;
  }
  res.writeHead(200, { 'Content-Type': MIME_TYPES[ext] ?? 'application/octet-stream' });
  res.end(data);
}

/**
 * Built-in plugin implementing the live-reload development server.
 *
 * During `onStart` it performs an initial build, starts an HTTP server that
 * serves the built site, and watches the content and template directories. On
 * change it rebuilds through the core engine and tells connected browsers to
 * reload.
 */
export class DevServerPlugin implements Plugin {
  readonly name = 'dev-server';

  private ctx!: PluginContext;
  private server!: Server;
  private wss!: WebSocketServer;
  private watcher!: chokidar.FSWatcher;
  private port: number = DEFAULT_PORT;
  private timer: NodeJS.Timeout | null = null;
  private queue: Promise<void> = Promise.resolve();

  async onStart(ctx: PluginContext): Promise<void> {
    this.ctx = ctx;
    await this.setup();
  }

  getServer(): DevServer {
    return {
      server: this.server,
      wss: this.wss,
      port: this.port,
      close: () => this.close(),
    };
  }

  private async setup(): Promise<void> {
    const options = this.ctx.options as ServeOptions;
    const contentDir = options.contentDir;
    const outputDir = options.outputDir;
    const templatesDir = options.templatesDir ?? 'templates';
    const port = options.port ?? DEFAULT_PORT;

    await this.ctx.engine.rebuild();

    const wss = new WebSocketServer({ noServer: true });
    this.wss = wss;

    const server = createServer((req, res) => {
      serveFile(req.url ?? '/', outputDir, res).catch(() => {
        res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Internal Server Error');
      });
    });
    this.server = server;

    server.on('upgrade', (req, socket, head) => {
      const pathname = (req.url ?? '').split('?')[0];
      if (pathname === LIVERELOAD_PATH) {
        wss.handleUpgrade(req, socket, head, (ws) => {
          wss.emit('connection', ws, req);
        });
      } else {
        socket.destroy();
      }
    });

    const watcher = chokidar.watch([contentDir, templatesDir], {
      ignoreInitial: true,
      ignored: (watchedPath: string) => {
        const normalized = path.resolve(watchedPath);
        const out = path.resolve(outputDir);
        if (normalized === out || normalized.startsWith(out + path.sep)) {
          return true;
        }
        const segments = normalized.split(path.sep);
        if (segments.includes('node_modules')) {
          return true;
        }
        if (path.basename(normalized).startsWith('.')) {
          return true;
        }
        return false;
      },
    });
    this.watcher = watcher;
    watcher.on('error', () => {
      // Watcher errors are non-fatal for the dev server.
    });

    const watcherReady = new Promise<void>((resolve) => {
      watcher.once('ready', resolve);
    });

    watcher.on('all', () => {
      if (this.timer) {
        clearTimeout(this.timer);
      }
      this.timer = setTimeout(() => {
        this.timer = null;
        this.queue = this.queue.then(() => this.rebuild());
      }, REBUILD_DEBOUNCE_MS);
    });

    await watcherReady;
    await new Promise<void>((resolve) => setTimeout(resolve, WATCHER_SETTLE_MS));

    await new Promise<void>((resolve, reject) => {
      server.once('error', reject);
      server.listen(port, () => {
        server.removeListener('error', reject);
        resolve();
      });
    });

    const address = server.address();
    this.port = address && typeof address === 'object' ? address.port : port;
  }

  private broadcast(message: string): void {
    for (const client of this.wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    }
  }

  private async rebuild(): Promise<void> {
    try {
      await this.ctx.engine.rebuild();
      this.broadcast('reload');
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      this.broadcast(JSON.stringify({ type: 'error', message }));
    }
  }

  private async close(): Promise<void> {
    if (this.timer) {
      clearTimeout(this.timer);
    }
    for (const client of this.wss.clients) {
      client.terminate();
    }
    await this.watcher.close();
    await new Promise<void>((resolve) => this.wss.close(() => resolve()));
    this.server.closeAllConnections();
    await new Promise<void>((resolve) => this.server.close(() => resolve()));
  }
}

import { loadConfig } from './config';
import { loadPlugins } from './loader';
import { SsgEngine } from './engine';
import { BuildOptions, Page } from './types';

/**
 * Build a static site from Markdown content.
 *
 * Delegates to the core SSG engine, which orchestrates the plugin pipeline
 * (markdown parsing, template rendering, and any configured plugins).
 */
export async function build(options: BuildOptions): Promise<Page[]> {
  const config = await loadConfig();
  const plugins = await loadPlugins(config);
  const engine = new SsgEngine(plugins, options, config);
  return engine.build();
}

import { createServer, Server } from 'http';
import { WebSocketServer } from 'ws';
import { loadConfig } from './config';
import { loadPlugins } from './loader';
import { SsgEngine } from './engine';
import { DevServerPlugin } from '../plugins/devserver';
import { BuildOptions } from './types';

export { injectReloadScript, reloadClientScript } from './livereload';

export interface ServeOptions extends BuildOptions {
  port?: number;
}

export interface DevServer {
  server: Server;
  wss: WebSocketServer;
  port: number;
  close(): Promise<void>;
}

/**
 * Start a live-reload development server.
 *
 * Delegates to the core SSG engine with the dev-server plugin loaded, which
 * performs an initial build, serves the built site from `outputDir`, watches
 * `contentDir` and `templatesDir` for changes, rebuilds on change, and tells
 * connected browsers to reload once a rebuild finishes.
 */
export async function startDevServer(options: ServeOptions): Promise<DevServer> {
  const config = await loadConfig();
  const plugins = await loadPlugins(config);
  plugins.push(new DevServerPlugin());
  const engine = new SsgEngine(plugins, options, config);
  return (await engine.serve()) as DevServer;
}

